[{"id":"2fbdb72","elType":"container","settings":[],"elements":[{"id":"4fdde1e","elType":"widget","settings":{"html":"<!--
  AM.TECH — премиальная страница «О компании»
  Готово для вставки одним блоком в Elementor → HTML.
  Все стили изолированы внутри #amt-about-premium.
-->

<style>
  #amt-about-premium {
    --amt-orange: #ff7300;
    --amt-orange-2: #ff9a3d;
    --amt-orange-soft: #fff3e9;
    --amt-ink: #171717;
    --amt-text: #4f4f4f;
    --amt-muted: #777;
    --amt-line: #e9e9e9;
    --amt-surface: #f7f7f5;
    --amt-white: #fff;
    --amt-dark: #171717;
    --amt-radius-xl: 34px;
    --amt-radius-lg: 24px;
    --amt-radius-md: 18px;
    --amt-shadow: 0 22px 70px rgba(22, 22, 22, 0.08);
    position: relative;
    width: 100%;
    overflow: hidden;
    color: var(--amt-ink);
    background: var(--amt-white);
    font-family: "Montserrat", Arial, sans-serif;
    line-height: 1.55;
    isolation: isolate;
  }

  #amt-about-premium,
  #amt-about-premium *,
  #amt-about-premium *::before,
  #amt-about-premium *::after {
    box-sizing: border-box;
  }

  #amt-about-premium a {
    color: inherit;
    text-decoration: none;
  }

  #amt-about-premium img,
  #amt-about-premium svg {
    display: block;
    max-width: 100%;
  }

  #amt-about-premium h1,
  #amt-about-premium h2,
  #amt-about-premium h3,
  #amt-about-premium p {
    margin: 0;
    padding: 0;
  }

  #amt-about-premium .amt-container {
    width: min(1180px, calc(100% - 48px));
    margin-inline: auto;
  }

  #amt-about-premium .amt-section {
    position: relative;
    padding: 112px 0;
  }

  #amt-about-premium [id] {
    scroll-margin-top: 110px;
  }

  #amt-about-premium .amt-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 22px;
    color: var(--amt-orange);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.2;
    letter-spacing: 0.14em;
    text-transform: uppercase;
  }

  #amt-about-premium .amt-eyebrow::before {
    width: 28px;
    height: 2px;
    content: "";
    background: currentColor;
  }

  #amt-about-premium .amt-title {
    max-width: 880px;
    font-size: clamp(38px, 5vw, 68px);
    font-weight: 760;
    line-height: 1.04;
    letter-spacing: -0.045em;
  }

  #amt-about-premium .amt-title--section {
    font-size: clamp(32px, 4vw, 52px);
    line-height: 1.08;
  }

  #amt-about-premium .amt-lead {
    max-width: 760px;
    color: var(--amt-text);
    font-size: clamp(17px, 1.6vw, 21px);
    line-height: 1.65;
  }

  #amt-about-premium .amt-highlight {
    color: var(--amt-orange);
  }

  #amt-about-premium .amt-button {
    min-height: 54px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 11px;
    padding: 14px 23px;
    border: 1px solid transparent;
    border-radius: 999px;
    appearance: none;
    cursor: pointer;
    font-family: inherit;
    font-size: 14px;
    font-weight: 760;
    line-height: 1;
    transition:
      transform 0.25s ease,
      box-shadow 0.25s ease,
      background-color 0.25s ease,
      color 0.25s ease;
  }

  #amt-about-premium .amt-button:hover {
    transform: translateY(-2px);
  }

  #amt-about-premium .amt-button--primary {
    color: var(--amt-white);
    background: var(--amt-orange);
    box-shadow: 0 12px 28px rgba(255, 115, 0, 0.28);
  }

  #amt-about-premium .amt-button--primary:hover {
    color: var(--amt-white);
    background: #e86500;
    box-shadow: 0 16px 34px rgba(255, 115, 0, 0.34);
  }

  #amt-about-premium .amt-button--secondary {
    color: var(--amt-ink);
    border-color: #d9d9d9;
    background: rgba(255, 255, 255, 0.72);
  }

  #amt-about-premium .amt-button--secondary:hover {
    border-color: var(--amt-orange);
    color: var(--amt-orange);
  }

  #amt-about-premium .amt-button svg {
    flex: 0 0 auto;
    width: 17px;
    height: 17px;
  }

  /* HERO */
  #amt-about-premium .amt-hero {
    position: relative;
    padding: 76px 0 42px;
    background:
      radial-gradient(circle at 84% 20%, rgba(255, 115, 0, 0.12), transparent 28%),
      linear-gradient(180deg, #fff 0%, #fbfbfa 100%);
  }

  #amt-about-premium .amt-hero::before {
    position: absolute;
    inset: 0;
    z-index: -1;
    content: "";
    opacity: 0.4;
    background-image:
      linear-gradient(rgba(30, 30, 30, 0.035) 1px, transparent 1px),
      linear-gradient(90deg, rgba(30, 30, 30, 0.035) 1px, transparent 1px);
    background-size: 42px 42px;
    mask-image: linear-gradient(to bottom, #000 30%, transparent 92%);
  }

  #amt-about-premium .amt-hero__grid {
    display: grid;
    grid-template-columns: minmax(0, 1.02fr) minmax(420px, 0.98fr);
    gap: 54px;
    align-items: center;
  }

  #amt-about-premium .amt-hero__copy {
    padding: 48px 0 36px;
  }

  #amt-about-premium .amt-hero h1 {
    max-width: 720px;
    font-size: clamp(43px, 5.2vw, 72px);
    font-weight: 770;
    line-height: 1.01;
    letter-spacing: -0.052em;
  }

  #amt-about-premium .amt-hero__lead {
    max-width: 680px;
    margin-top: 28px;
    color: var(--amt-text);
    font-size: clamp(17px, 1.55vw, 20px);
    line-height: 1.68;
  }

  #amt-about-premium .amt-hero__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 34px;
  }

  #amt-about-premium .amt-hero__trust {
    display: flex;
    flex-wrap: wrap;
    gap: 20px 28px;
    margin-top: 38px;
    color: #5d5d5d;
    font-size: 12px;
    font-weight: 720;
    letter-spacing: 0.01em;
  }

  #amt-about-premium .amt-hero__trust span {
    display: inline-flex;
    align-items: center;
    gap: 8px;
  }

  #amt-about-premium .amt-hero__trust i {
    width: 19px;
    height: 19px;
    display: inline-grid;
    place-items: center;
    border-radius: 50%;
    color: var(--amt-white);
    background: var(--amt-orange);
    font-size: 11px;
    font-style: normal;
    font-weight: 800;
  }

  #amt-about-premium .amt-core {
    position: relative;
    min-height: 560px;
    display: grid;
    place-items: center;
  }

  #amt-about-premium .amt-core__rings {
    position: absolute;
    inset: 50% auto auto 50%;
    width: min(94%, 540px);
    aspect-ratio: 1;
    transform: translate(-50%, -50%);
    border: 1px solid rgba(255, 115, 0, 0.2);
    border-radius: 50%;
  }

  #amt-about-premium .amt-core__rings::before,
  #amt-about-premium .amt-core__rings::after {
    position: absolute;
    inset: 50% auto auto 50%;
    aspect-ratio: 1;
    content: "";
    transform: translate(-50%, -50%);
    border: 1px solid rgba(255, 115, 0, 0.16);
    border-radius: 50%;
  }

  #amt-about-premium .amt-core__rings::before {
    width: 72%;
  }

  #amt-about-premium .amt-core__rings::after {
    width: 48%;
  }

  #amt-about-premium .amt-core__axis {
    position: absolute;
    inset: 50% auto auto 50%;
    width: 78%;
    height: 78%;
    transform: translate(-50%, -50%) rotate(45deg);
  }

  #amt-about-premium .amt-core__axis::before,
  #amt-about-premium .amt-core__axis::after {
    position: absolute;
    content: "";
    background: linear-gradient(90deg, transparent, rgba(255, 115, 0, 0.25), transparent);
  }

  #amt-about-premium .amt-core__axis::before {
    top: 50%;
    left: 0;
    width: 100%;
    height: 1px;
  }

  #amt-about-premium .amt-core__axis::after {
    top: 0;
    left: 50%;
    width: 1px;
    height: 100%;
    background: linear-gradient(180deg, transparent, rgba(255, 115, 0, 0.25), transparent);
  }

  #amt-about-premium .amt-core__center {
    position: relative;
    z-index: 2;
    width: 210px;
    aspect-ratio: 1;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255, 115, 0, 0.28);
    border-radius: 50%;
    color: var(--amt-white);
    background:
      radial-gradient(circle at 35% 28%, #444 0%, #242424 38%, #131313 100%);
    box-shadow:
      0 35px 80px rgba(20, 20, 20, 0.22),
      inset 0 0 0 10px rgba(255, 255, 255, 0.035);
    text-align: center;
  }

  #amt-about-premium .amt-core__mark {
    font-size: 29px;
    font-weight: 820;
    line-height: 1;
    letter-spacing: -0.05em;
  }

  #amt-about-premium .amt-core__mark span {
    color: var(--amt-orange);
  }

  #amt-about-premium .amt-core__mark small {
    display: block;
    margin-top: 10px;
    color: #bcbcbc;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  #amt-about-premium .amt-core__node {
    position: absolute;
    z-index: 3;
    min-width: 152px;
    padding: 14px 16px;
    border: 1px solid rgba(25, 25, 25, 0.08);
    border-radius: 15px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: 0 14px 40px rgba(25, 25, 25, 0.1);
    backdrop-filter: blur(10px);
  }

  #amt-about-premium .amt-core__node::before {
    width: 8px;
    height: 8px;
    display: inline-block;
    margin-right: 8px;
    border-radius: 50%;
    content: "";
    background: var(--amt-orange);
    box-shadow: 0 0 0 5px rgba(255, 115, 0, 0.13);
  }

  #amt-about-premium .amt-core__node strong {
    font-size: 12px;
    font-weight: 790;
  }

  #amt-about-premium .amt-core__node small {
    display: block;
    margin-top: 5px;
    color: var(--amt-muted);
    font-size: 10px;
    line-height: 1.35;
  }

  #amt-about-premium .amt-core__node--one {
    top: 8%;
    left: 5%;
  }

  #amt-about-premium .amt-core__node--two {
    top: 14%;
    right: 0;
  }

  #amt-about-premium .amt-core__node--three {
    right: 2%;
    bottom: 10%;
  }

  #amt-about-premium .amt-core__node--four {
    bottom: 4%;
    left: 0;
  }

  #amt-about-premium .amt-facts {
    position: relative;
    z-index: 4;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-top: 20px;
  }

  #amt-about-premium .amt-fact {
    min-height: 136px;
    padding: 24px;
    border: 1px solid var(--amt-line);
    border-radius: var(--amt-radius-md);
    background: rgba(255, 255, 255, 0.92);
    box-shadow: 0 10px 35px rgba(20, 20, 20, 0.045);
  }

  #amt-about-premium .amt-fact__value {
    color: var(--amt-orange);
    font-size: clamp(25px, 3vw, 38px);
    font-weight: 810;
    line-height: 1;
    letter-spacing: -0.04em;
  }

  #amt-about-premium .amt-fact__label {
    max-width: 220px;
    margin-top: 13px;
    color: #565656;
    font-size: 13px;
    font-weight: 650;
    line-height: 1.4;
  }

  /* STICKY-LIKE ANCHOR NAV */
  #amt-about-premium .amt-anchor-wrap {
    position: relative;
    z-index: 8;
    padding: 20px 0;
    border-top: 1px solid #ededed;
    border-bottom: 1px solid #ededed;
    background: rgba(255, 255, 255, 0.92);
    backdrop-filter: blur(14px);
  }

  #amt-about-premium .amt-anchor-nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
  }

  #amt-about-premium .amt-anchor-nav__brand {
    flex: 0 0 auto;
    color: var(--amt-ink);
    font-size: 13px;
    font-weight: 820;
    letter-spacing: 0.06em;
  }

  #amt-about-premium .amt-anchor-nav__brand span {
    color: var(--amt-orange);
  }

  #amt-about-premium .amt-anchor-nav__links {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 8px;
  }

  #amt-about-premium .amt-anchor-nav__links a {
    padding: 9px 13px;
    border-radius: 999px;
    color: #5e5e5e;
    font-size: 12px;
    font-weight: 680;
    transition:
      color 0.2s ease,
      background-color 0.2s ease;
  }

  #amt-about-premium .amt-anchor-nav__links a:hover {
    color: var(--amt-orange);
    background: var(--amt-orange-soft);
  }

  /* ENGINEERING CORE */
  #amt-about-premium .amt-engineering {
    background: var(--amt-white);
  }

  #amt-about-premium .amt-engineering__grid {
    display: grid;
    grid-template-columns: minmax(0, 0.92fr) minmax(440px, 1.08fr);
    gap: 72px;
    align-items: center;
  }

  #amt-about-premium .amt-engineering__copy .amt-lead {
    margin-top: 24px;
  }

  #amt-about-premium .amt-checks {
    display: grid;
    gap: 20px;
    margin-top: 34px;
  }

  #amt-about-premium .amt-check {
    display: grid;
    grid-template-columns: 44px 1fr;
    gap: 15px;
    align-items: start;
  }

  #amt-about-premium .amt-check__icon {
    width: 44px;
    height: 44px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255, 115, 0, 0.18);
    border-radius: 13px;
    color: var(--amt-orange);
    background: var(--amt-orange-soft);
  }

  #amt-about-premium .amt-check__icon svg {
    width: 21px;
    height: 21px;
  }

  #amt-about-premium .amt-check h3 {
    padding-top: 1px;
    font-size: 16px;
    font-weight: 770;
    line-height: 1.35;
  }

  #amt-about-premium .amt-check p {
    margin-top: 5px;
    color: var(--amt-muted);
    font-size: 13px;
    line-height: 1.55;
  }

  #amt-about-premium .amt-engineering__visual {
    position: relative;
    min-height: 570px;
  }

  #amt-about-premium .amt-engineering__image {
    position: absolute;
    inset: 0 0 54px 0;
    overflow: hidden;
    border-radius: var(--amt-radius-xl);
    background: #242424;
    box-shadow: var(--amt-shadow);
  }

  #amt-about-premium .amt-engineering__image::after {
    position: absolute;
    inset: 0;
    content: "";
    background:
      linear-gradient(180deg, transparent 50%, rgba(15, 15, 15, 0.36) 100%),
      linear-gradient(90deg, rgba(255, 115, 0, 0.12), transparent 48%);
  }

  #amt-about-premium .amt-engineering__image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: 58% center;
  }

  #amt-about-premium .amt-engineering__metric {
    position: absolute;
    right: 28px;
    bottom: 0;
    z-index: 2;
    width: min(330px, calc(100% - 56px));
    padding: 23px 25px;
    border: 1px solid rgba(255, 115, 0, 0.18);
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.95);
    box-shadow: 0 20px 55px rgba(25, 25, 25, 0.16);
    backdrop-filter: blur(12px);
  }

  #amt-about-premium .amt-engineering__metric-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
  }

  #amt-about-premium .amt-engineering__metric strong {
    max-width: 190px;
    font-size: 13px;
    line-height: 1.35;
  }

  #amt-about-premium .amt-engineering__metric b {
    color: var(--amt-orange);
    font-size: 28px;
    line-height: 1;
  }

  #amt-about-premium .amt-progress {
    height: 7px;
    margin-top: 15px;
    overflow: hidden;
    border-radius: 999px;
    background: #ededed;
  }

  #amt-about-premium .amt-progress span {
    width: 54%;
    height: 100%;
    display: block;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--amt-orange), var(--amt-orange-2));
  }

  #amt-about-premium .amt-engineering__metric small {
    display: block;
    margin-top: 11px;
    color: var(--amt-muted);
    font-size: 10px;
    line-height: 1.45;
  }

  /* TECHNOLOGY MAP */
  #amt-about-premium .amt-tech {
    background:
      radial-gradient(circle at 10% 10%, rgba(255, 115, 0, 0.08), transparent 25%),
      var(--amt-surface);
  }

  #amt-about-premium .amt-tech__head {
    display: grid;
    grid-template-columns: minmax(0, 0.9fr) minmax(320px, 0.55fr);
    gap: 50px;
    align-items: end;
  }

  #amt-about-premium .amt-tech__head .amt-lead {
    justify-self: end;
    font-size: 16px;
  }

  #amt-about-premium .amt-tech__grid {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    gap: 16px;
    margin-top: 54px;
  }

  #amt-about-premium .amt-tech-card {
    grid-column: span 3;
    min-height: 210px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 24px;
    overflow: hidden;
    border: 1px solid rgba(20, 20, 20, 0.07);
    border-radius: var(--amt-radius-lg);
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 12px 38px rgba(20, 20, 20, 0.045);
    transition:
      transform 0.25s ease,
      border-color 0.25s ease,
      box-shadow 0.25s ease;
  }

  #amt-about-premium .amt-tech-card:hover {
    transform: translateY(-4px);
    border-color: rgba(255, 115, 0, 0.3);
    box-shadow: 0 18px 45px rgba(20, 20, 20, 0.08);
  }

  #amt-about-premium .amt-tech-card--wide {
    grid-column: span 6;
    min-height: 230px;
    color: var(--amt-white);
    border-color: transparent;
    background:
      radial-gradient(circle at 86% 10%, rgba(255, 115, 0, 0.32), transparent 32%),
      #1c1c1c;
  }

  #amt-about-premium .amt-tech-card__top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
  }

  #amt-about-premium .amt-tech-card__code {
    color: var(--amt-orange);
    font-size: clamp(27px, 3.4vw, 44px);
    font-weight: 820;
    line-height: 1;
    letter-spacing: -0.05em;
  }

  #amt-about-premium .amt-tech-card__index {
    color: #b3b3b3;
    font-size: 10px;
    font-weight: 740;
    letter-spacing: 0.14em;
  }

  #amt-about-premium .amt-tech-card h3 {
    margin-top: 22px;
    font-size: 14px;
    font-weight: 760;
    line-height: 1.35;
  }

  #amt-about-premium .amt-tech-card p {
    margin-top: 8px;
    color: var(--amt-muted);
    font-size: 11px;
    line-height: 1.5;
  }

  #amt-about-premium .amt-tech-card--wide p {
    max-width: 420px;
    color: #bdbdbd;
  }

  #amt-about-premium .amt-tech-card__scan {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 46%;
    height: 100%;
    opacity: 0.55;
  }

  #amt-about-premium .amt-tech-card--wide {
    position: relative;
  }

  /* SERVICES */
  #amt-about-premium .amt-services {
    background: var(--amt-white);
  }

  #amt-about-premium .amt-services__head {
    display: flex;
    align-items: end;
    justify-content: space-between;
    gap: 30px;
  }

  #amt-about-premium .amt-services__head .amt-lead {
    max-width: 420px;
    font-size: 16px;
  }

  #amt-about-premium .amt-services__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-top: 54px;
  }

  #amt-about-premium .amt-service {
    min-width: 0;
    overflow: hidden;
    border: 1px solid var(--amt-line);
    border-radius: var(--amt-radius-lg);
    background: var(--amt-white);
    box-shadow: 0 12px 35px rgba(20, 20, 20, 0.045);
    transition:
      transform 0.25s ease,
      box-shadow 0.25s ease;
  }

  #amt-about-premium .amt-service:hover {
    transform: translateY(-4px);
    box-shadow: 0 22px 48px rgba(20, 20, 20, 0.09);
  }

  #amt-about-premium .amt-service__media {
    position: relative;
    height: 210px;
    overflow: hidden;
    background: #e7e7e7;
  }

  #amt-about-premium .amt-service__media::after {
    position: absolute;
