<script>
(function () {
  var modal = document.getElementById('amt-engineer-form-modal');
  var openButtons = document.querySelectorAll('[data-amt-form-open]');
  var closeButton = modal ? modal.querySelector('[data-amt-form-close]') : null;
  var lastFocusedElement = null;
  var previousBodyOverflow = '';

  if (!modal || !openButtons.length || !closeButton) {
    return;
  }

  function openForm() {
    lastFocusedElement = document.activeElement;
    previousBodyOverflow = document.body.style.overflow;
    modal.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
    closeButton.focus();
  }

  function closeForm() {
    modal.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = previousBodyOverflow;

    if (lastFocusedElement) {
      lastFocusedElement.focus();
    }
  }

  openButtons.forEach(function (button) {
    button.addEventListener('click', openForm);
  });

  closeButton.addEventListener('click', closeForm);

  modal.addEventListener('click', function (event) {
    if (event.target === modal) {
      closeForm();
    }
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') {
      closeForm();
    }
  });
})();
</script>

